package onboarding

import (
	"fmt"
	"strings"
)

const (
	OnboardStepModel     = "model"
	OnboardStepProvider  = "provider"
	OnboardStepAuth      = "auth"
	OnboardStepGateway   = "gateway"
	OnboardStepBrowser   = "browser"
	OnboardStepSkills    = "skills"
	OnboardStepDashboard = "dashboard"

	OnboardStatusConfigured = "configured"
	OnboardStatusMissing    = "missing"
	OnboardStatusAvailable  = "available"
)

type OnboardPlanInput struct {
	Provider       string
	Endpoint       string
	Model          string
	APIKeyPresent  bool
	GatewayTargets []string
	BrowserCDPURL  string
	LocalSkills    int
	BundledSkills  int
}

type OnboardPlan struct {
	Steps []OnboardStep
}

type OnboardStep struct {
	ID          string
	Title       string
	Status      string
	Detail      string
	NextCommand string
	SkipWarning string
}

func BuildOnboardPlan(input OnboardPlanInput) OnboardPlan {
	provider := strings.TrimSpace(input.Provider)
	endpoint := strings.TrimSpace(input.Endpoint)
	model := strings.TrimSpace(input.Model)
	browserCDPURL := strings.TrimSpace(input.BrowserCDPURL)

	modelStep := OnboardStep{
		ID:          OnboardStepModel,
		Title:       "Model",
		Status:      OnboardStatusMissing,
		Detail:      "No default model is configured.",
		NextCommand: "gormes setup model",
		SkipWarning: "Skipping model selection leaves the runtime on built-in defaults or provider-specific fallback behavior.",
	}
	if model != "" {
		modelStep.Status = OnboardStatusConfigured
		modelStep.Detail = fmt.Sprintf("Default model %s will be pre-filled.", model)
	}

	providerStep := OnboardStep{
		ID:          OnboardStepProvider,
		Title:       "Provider",
		Status:      OnboardStatusMissing,
		Detail:      "No provider endpoint is configured.",
		NextCommand: "gormes setup provider",
		SkipWarning: "Skipping provider setup means agents cannot make provider-backed turns until endpoint and model settings are added.",
	}
	if provider != "" || endpoint != "" {
		providerStep.Status = OnboardStatusConfigured
		providerStep.Detail = fmt.Sprintf("Provider %s at %s will be pre-filled.", providerLabel(provider), endpointLabel(endpoint))
	}

	authStep := OnboardStep{
		ID:          OnboardStepAuth,
		Title:       "Auth",
		Status:      OnboardStatusMissing,
		Detail:      "No provider credential was found.",
		NextCommand: "gormes auth add <provider>",
		SkipWarning: "Skipping auth leaves provider calls unavailable until a credential is stored or exported.",
	}
	if input.APIKeyPresent {
		authStep.Status = OnboardStatusConfigured
		authStep.Detail = "Provider credential present; secret value is not shown."
	}

	gatewayStep := OnboardStep{
		ID:          OnboardStepGateway,
		Title:       "Gateway",
		Status:      OnboardStatusMissing,
		Detail:      "No messaging platform is configured.",
		NextCommand: "gormes setup gateway",
		SkipWarning: "Skipping gateway setup keeps Telegram, Discord, Slack, and other messaging adapters disabled.",
	}
	if len(input.GatewayTargets) > 0 {
		gatewayStep.Status = OnboardStatusConfigured
		gatewayStep.Detail = "Configured messaging targets: " + strings.Join(input.GatewayTargets, ", ")
	}

	browserStep := OnboardStep{
		ID:          OnboardStepBrowser,
		Title:       "Browser/CDP",
		Status:      OnboardStatusMissing,
		Detail:      "No browser/CDP endpoint is configured.",
		NextCommand: "gormes doctor --offline",
		SkipWarning: "Skipping browser checks leaves browser automation unavailable until a local or cloud browser backend is configured.",
	}
	if browserCDPURL != "" {
		browserStep.Status = OnboardStatusConfigured
		browserStep.Detail = "Browser/CDP endpoint will be pre-filled: " + browserCDPURL
	}

	skillsStep := OnboardStep{
		ID:          OnboardStepSkills,
		Title:       "Skills",
		Status:      OnboardStatusAvailable,
		Detail:      fmt.Sprintf("Skill discovery sees %d local and %d bundled skills.", input.LocalSkills, input.BundledSkills),
		NextCommand: "gormes skills list",
		SkipWarning: "Skipping skill discovery means the runtime will still use configured skills, but the operator has not reviewed what is installed.",
	}

	dashboardStep := OnboardStep{
		ID:          OnboardStepDashboard,
		Title:       "Dashboard",
		Status:      OnboardStatusAvailable,
		Detail:      "Dashboard launch is available as a manual step.",
		NextCommand: "gormes dashboard",
		SkipWarning: "Skipping dashboard launch keeps onboarding in the terminal; runtime state can still be inspected with CLI commands.",
	}

	return OnboardPlan{Steps: []OnboardStep{
		modelStep,
		providerStep,
		authStep,
		gatewayStep,
		browserStep,
		skillsStep,
		dashboardStep,
	}}
}

func (p OnboardPlan) Step(id string) (OnboardStep, bool) {
	for _, step := range p.Steps {
		if step.ID == id {
			return step, true
		}
	}
	return OnboardStep{}, false
}

func providerLabel(provider string) string {
	if provider == "" {
		return "custom"
	}
	return provider
}

func endpointLabel(endpoint string) string {
	if endpoint == "" {
		return "(manual endpoint)"
	}
	return endpoint
}

package onboarding

import (
	"fmt"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/platform/textvalue"
)

type SetupTargetID string

const (
	SetupTargetTerminal SetupTargetID = "terminal"
	SetupTargetTelegram SetupTargetID = "telegram"
	SetupTargetWhatsApp SetupTargetID = "whatsapp"
	SetupTargetDiscord  SetupTargetID = "discord"
	SetupTargetSlack    SetupTargetID = "slack"
	SetupTargetNavivox  SetupTargetID = "navivox"
)

type FirstRunActionID string

const (
	FirstRunActionQuick           FirstRunActionID = "quick"
	FirstRunActionFull            FirstRunActionID = "full"
	FirstRunActionMigrateHermes   FirstRunActionID = "migrate_hermes"
	FirstRunActionMigrateOpenClaw FirstRunActionID = "migrate_openclaw"
)

type FirstRunStepID string

const (
	FirstRunStepProvider FirstRunStepID = "provider"
	FirstRunStepAuth     FirstRunStepID = "auth"
	FirstRunStepModel    FirstRunStepID = "model"
	FirstRunStepChannel  FirstRunStepID = "channel"
)

type FirstRunPlanInput struct {
	Interactive        bool
	Provider           string
	Endpoint           string
	Model              string
	APIKeyPresent      bool
	Target             SetupTargetID
	Channels           []ChannelState
	HermesSourcePath   string
	OpenClawSourcePath string
}

type ChannelState struct {
	Target         SetupTargetID
	Label          string
	Configured     bool
	Detail         string
	SetupCommand   string
	HandoffCommand string
}

type SetupTargetOption struct {
	ID             SetupTargetID
	Label          string
	Channel        bool
	Configured     bool
	Detail         string
	SetupCommand   string
	HandoffCommand string
}

type FirstRunAction struct {
	ID        FirstRunActionID
	Label     string
	Available bool
	Detail    string
	Command   string
}

type FirstRunStep struct {
	ID      FirstRunStepID
	Label   string
	Detail  string
	Command string
}

type FirstRunPlan struct {
	Ready         bool
	PromptAllowed bool
	Target        SetupTargetID
	TargetLabel   string
	DefaultTarget SetupTargetID
	Targets       []SetupTargetOption
	Actions       []FirstRunAction
	DefaultAction FirstRunActionID
	MissingSteps  []FirstRunStep
	NextCommand   string
	Summary       string
}

func BuildFirstRunPlan(input FirstRunPlanInput) FirstRunPlan {
	target := normalizeSetupTarget(input.Target)
	targets := buildFirstRunTargets(input, target)
	selected := findFirstRunTarget(targets, target)
	coreReady := textvalue.IsNonBlank(input.Endpoint) && textvalue.IsNonBlank(input.Model) && input.APIKeyPresent
	channelConfigured := !selected.Channel || firstRunChannelConfigured(input.Channels, target)

	plan := FirstRunPlan{
		PromptAllowed: input.Interactive,
		Target:        target,
		TargetLabel:   selected.Label,
		DefaultTarget: SetupTargetNavivox,
		Targets:       targets,
		Actions:       buildFirstRunActions(input, target),
		DefaultAction: FirstRunActionQuick,
	}

	setupCommand := selected.SetupCommand
	if setupCommand == "" {
		setupCommand = defaultSetupCommand(target)
	}
	if !textvalue.IsNonBlank(input.Endpoint) {
		plan.MissingSteps = append(plan.MissingSteps, FirstRunStep{
			ID:      FirstRunStepProvider,
			Label:   "Provider",
			Detail:  "provider endpoint is not configured",
			Command: quickSetupCommand(target),
		})
	}
	if !input.APIKeyPresent {
		provider := strings.TrimSpace(input.Provider)
		command := "gormes setup provider"
		if provider != "" {
			command = "gormes auth add " + provider
		}
		plan.MissingSteps = append(plan.MissingSteps, FirstRunStep{
			ID:      FirstRunStepAuth,
			Label:   "Authentication",
			Detail:  "provider credential is not configured",
			Command: command,
		})
	}
	if !textvalue.IsNonBlank(input.Model) {
		plan.MissingSteps = append(plan.MissingSteps, FirstRunStep{
			ID:      FirstRunStepModel,
			Label:   "Model",
			Detail:  "model is not configured",
			Command: "gormes setup model",
		})
	}
	if selected.Channel && !channelConfigured {
		plan.MissingSteps = append(plan.MissingSteps, FirstRunStep{
			ID:      FirstRunStepChannel,
			Label:   selected.Label,
			Detail:  selected.Label + " channel is not configured",
			Command: setupCommand,
		})
	}

	plan.Ready = coreReady && channelConfigured
	if plan.Ready {
		plan.NextCommand = selected.HandoffCommand
		if plan.NextCommand == "" {
			plan.NextCommand = defaultHandoffCommand(target)
		}
		if selected.Channel {
			plan.Summary = selected.Label + " is ready"
		} else {
			plan.Summary = "terminal chat is ready"
		}
		return plan
	}

	if len(plan.MissingSteps) > 0 {
		plan.NextCommand = plan.MissingSteps[0].Command
		plan.Summary = "not ready: " + plan.MissingSteps[0].Detail
	} else {
		plan.NextCommand = setupCommand
		plan.Summary = "not ready"
	}
	return plan
}

func (p FirstRunPlan) Step(id FirstRunStepID) (FirstRunStep, bool) {
	for _, step := range p.MissingSteps {
		if step.ID == id {
			return step, true
		}
	}
	return FirstRunStep{}, false
}

func DefaultFirstRunChannels(overrides map[SetupTargetID]ChannelState) []ChannelState {
	channels := []ChannelState{
		defaultFirstRunChannel(SetupTargetTelegram),
		defaultFirstRunChannel(SetupTargetWhatsApp),
		defaultFirstRunChannel(SetupTargetDiscord),
		defaultFirstRunChannel(SetupTargetSlack),
		defaultFirstRunChannel(SetupTargetNavivox),
	}

	for i := range channels {
		override, ok := overrides[channels[i].Target]
		if !ok {
			continue
		}
		channels[i] = mergeChannelState(channels[i], override)
	}
	return channels
}

func buildFirstRunTargets(input FirstRunPlanInput, selected SetupTargetID) []SetupTargetOption {
	coreConfigured := textvalue.IsNonBlank(input.Endpoint) && textvalue.IsNonBlank(input.Model) && input.APIKeyPresent
	targets := []SetupTargetOption{{
		ID:             SetupTargetTerminal,
		Label:          "Terminal",
		Configured:     coreConfigured,
		Detail:         "terminal chat",
		SetupCommand:   defaultSetupCommand(SetupTargetTerminal),
		HandoffCommand: defaultHandoffCommand(SetupTargetTerminal),
	}}

	channelByTarget := map[SetupTargetID]ChannelState{}
	for _, channel := range DefaultFirstRunChannels(nil) {
		channelByTarget[channel.Target] = channel
	}
	for _, channel := range input.Channels {
		normalized := normalizeSetupTarget(channel.Target)
		if !isChannelTarget(normalized) {
			continue
		}
		channel.Target = normalized
		channelByTarget[normalized] = mergeChannelState(defaultFirstRunChannel(normalized), channel)
	}

	for _, id := range []SetupTargetID{
		SetupTargetTelegram,
		SetupTargetWhatsApp,
		SetupTargetDiscord,
		SetupTargetSlack,
		SetupTargetNavivox,
	} {
		channel := channelByTarget[id]
		targets = append(targets, SetupTargetOption{
			ID:             id,
			Label:          channel.Label,
			Channel:        true,
			Configured:     coreConfigured && channel.Configured,
			Detail:         channel.Detail,
			SetupCommand:   channel.SetupCommand,
			HandoffCommand: channel.HandoffCommand,
		})
	}

	if findFirstRunTarget(targets, selected).ID == "" {
		return buildFirstRunTargets(input, SetupTargetTerminal)
	}
	return targets
}

func buildFirstRunActions(input FirstRunPlanInput, target SetupTargetID) []FirstRunAction {
	actions := []FirstRunAction{
		{
			ID:        FirstRunActionQuick,
			Label:     "Quick setup",
			Available: true,
			Detail:    "configure the selected target with the shortest setup path",
			Command:   quickSetupCommand(target),
		},
		{
			ID:        FirstRunActionFull,
			Label:     "Full setup",
			Available: true,
			Detail:    "walk through provider, model, credentials, and channel setup",
			Command:   "gormes setup --target " + string(target),
		},
	}
	if path := strings.TrimSpace(input.HermesSourcePath); path != "" {
		actions = append(actions, FirstRunAction{
			ID:        FirstRunActionMigrateHermes,
			Label:     "Migrate Hermes",
			Available: true,
			Detail:    "import settings from an existing Hermes install",
			Command:   fmt.Sprintf("gormes migrate hermes --dry-run --source %s", shellQuoteFirstRunArg(path)),
		})
	}
	if path := strings.TrimSpace(input.OpenClawSourcePath); path != "" {
		actions = append(actions, FirstRunAction{
			ID:        FirstRunActionMigrateOpenClaw,
			Label:     "Migrate OpenClaw",
			Available: true,
			Detail:    "import settings from an existing OpenClaw install",
			Command:   fmt.Sprintf("gormes migrate openclaw --dry-run --source %s", shellQuoteFirstRunArg(path)),
		})
	}
	return actions
}

func shellQuoteFirstRunArg(value string) string {
	return "'" + strings.ReplaceAll(value, "'", "'\"'\"'") + "'"
}

func firstRunChannelConfigured(channels []ChannelState, target SetupTargetID) bool {
	target = normalizeSetupTarget(target)
	if !isChannelTarget(target) {
		return true
	}
	for _, channel := range channels {
		if normalizeSetupTarget(channel.Target) == target {
			return channel.Configured
		}
	}
	return false
}

func findFirstRunTarget(targets []SetupTargetOption, id SetupTargetID) SetupTargetOption {
	for _, target := range targets {
		if target.ID == id {
			return target
		}
	}
	return SetupTargetOption{}
}

func defaultFirstRunChannel(id SetupTargetID) ChannelState {
	id = normalizeSetupTarget(id)
	return ChannelState{
		Target:         id,
		Label:          setupTargetLabel(id),
		Detail:         setupTargetLabel(id) + " channel",
		SetupCommand:   defaultSetupCommand(id),
		HandoffCommand: defaultHandoffCommand(id),
	}
}

func mergeChannelState(base, override ChannelState) ChannelState {
	if normalized := normalizeSetupTarget(override.Target); isChannelTarget(normalized) {
		base.Target = normalized
	}
	if override.Label != "" {
		base.Label = override.Label
	}
	base.Configured = override.Configured
	if override.Detail != "" {
		base.Detail = override.Detail
	}
	if override.SetupCommand != "" {
		base.SetupCommand = override.SetupCommand
	}
	if override.HandoffCommand != "" {
		base.HandoffCommand = override.HandoffCommand
	}
	return base
}

func normalizeSetupTarget(id SetupTargetID) SetupTargetID {
	switch SetupTargetID(textvalue.LowerTrim(string(id))) {
	case "", SetupTargetTerminal, "chat", "tui":
		return SetupTargetTerminal
	case SetupTargetTelegram:
		return SetupTargetTelegram
	case SetupTargetWhatsApp, "wa":
		return SetupTargetWhatsApp
	case SetupTargetDiscord:
		return SetupTargetDiscord
	case SetupTargetSlack:
		return SetupTargetSlack
	case SetupTargetNavivox:
		return SetupTargetNavivox
	default:
		return SetupTargetTerminal
	}
}

func isChannelTarget(id SetupTargetID) bool {
	switch id {
	case SetupTargetTelegram, SetupTargetWhatsApp, SetupTargetDiscord, SetupTargetSlack, SetupTargetNavivox:
		return true
	default:
		return false
	}
}

func setupTargetLabel(id SetupTargetID) string {
	switch id {
	case SetupTargetTelegram:
		return "Telegram"
	case SetupTargetWhatsApp:
		return "WhatsApp"
	case SetupTargetDiscord:
		return "Discord"
	case SetupTargetSlack:
		return "Slack"
	case SetupTargetNavivox:
		return "Navivox"
	default:
		return "Terminal"
	}
}

func defaultSetupCommand(id SetupTargetID) string {
	id = normalizeSetupTarget(id)
	if id == SetupTargetWhatsApp {
		return "gormes whatsapp --plan"
	}
	return quickSetupCommand(id)
}

func quickSetupCommand(id SetupTargetID) string {
	return "gormes setup --quick --target " + string(normalizeSetupTarget(id))
}

func defaultHandoffCommand(id SetupTargetID) string {
	if normalizeSetupTarget(id) == SetupTargetTerminal {
		return "gormes"
	}
	return "gormes gateway"
}

package onboarding

import "github.com/TrebuchetDynamics/gormes-agent/internal/platform/textvalue"

const (
	// BusyInputPromptFlag is the stable onboarding.seen key for the one-time
	// busy-input behavior hint.
	BusyInputPromptFlag = "busy_input_prompt"
	// ToolProgressPromptFlag is the stable onboarding.seen key for the
	// one-time tool-progress behavior hint.
	ToolProgressPromptFlag = "tool_progress_prompt"
)

// BusyInputHint returns the one-time operator hint shown after the first input
// received while a turn is already running. It is pure text: callers own seen
// state, persistence, transport, and active-turn policy.
func BusyInputHint(surface, mode string) string {
	surface = normalizeOnboardingSurface(surface)
	switch normalizeBusyInputMode(mode) {
	case "queue":
		if surface == "gateway" {
			return "First-time tip: I queued your message instead of interrupting. Send /busy interrupt to make new messages stop the current task immediately, or /busy status to check. This tip only shows once."
		}
		return "(tip) Your message was queued for the next turn. Use /busy interrupt to make new input stop the current run instead, or /busy steer to inject mid-run. This tip only shows once."
	case "steer":
		if surface == "gateway" {
			return "First-time tip: I steered your message into the current run; it will arrive after the next tool call instead of interrupting. Send /busy interrupt or /busy queue to change this, or /busy status to check. This tip only shows once."
		}
		return "(tip) Your message was steered into the current run; it arrives after the next tool call. Use /busy interrupt or /busy queue to change this. This tip only shows once."
	default:
		if surface == "gateway" {
			return "First-time tip: I interrupted the current task to handle your message. Send /busy queue to queue follow-ups for after the current task, /busy steer to inject them mid-run, or /busy status to check. This tip only shows once."
		}
		return "(tip) Your message interrupted the current run. Use /busy queue to queue messages for the next turn instead, or /busy steer to inject mid-run. This tip only shows once."
	}
}

// ToolProgressHint returns the one-time operator hint shown when long-running
// tool progress is first surfaced. It does not inspect or mutate display mode.
func ToolProgressHint(surface string) string {
	if normalizeOnboardingSurface(surface) == "gateway" {
		return "First-time tip: long-running tool progress is being shown. Send /verbose to cycle progress modes (all -> new -> off). This tip only shows once."
	}
	return "(tip) Long-running tool progress is being shown. Use /verbose to cycle progress display modes (all -> new -> off). This tip only shows once."
}

func normalizeOnboardingSurface(surface string) string {
	switch textvalue.LowerTrim(surface) {
	case "gateway", "channel", "telegram", "discord", "slack":
		return "gateway"
	default:
		return "cli"
	}
}

func normalizeBusyInputMode(mode string) string {
	switch textvalue.LowerTrim(mode) {
	case "queue":
		return "queue"
	case "steer":
		return "steer"
	default:
		return "interrupt"
	}
}

package onboarding

const (
	// OpenClawResidueCleanupFlag is the stable onboarding.seen key for the
	// one-time OpenClaw residue cleanup banner.
	OpenClawResidueCleanupFlag = "openclaw_residue_cleanup"
	OpenClawResidueFlag        = OpenClawResidueCleanupFlag
)

// OnboardingSeen reports whether config has onboarding.seen.<flag> set to
// true. With no flag argument, it checks the OpenClaw residue cleanup flag.
// Malformed or missing onboarding maps are treated as unseen.
func OnboardingSeen(config map[string]any, flags ...string) bool {
	seen, ok := onboardingSeenMap(config)
	if !ok {
		return false
	}
	value, ok := seen[onboardingFlag(flags)].(bool)
	return ok && value
}

// MarkOnboardingSeen sets onboarding.seen.<flag> to true in memory and returns
// the corrected config map. With no flag argument, it marks the OpenClaw
// residue cleanup flag.
func MarkOnboardingSeen(config map[string]any, flags ...string) map[string]any {
	if config == nil {
		config = map[string]any{}
	}

	onboarding, ok := config["onboarding"].(map[string]any)
	if !ok {
		onboarding = map[string]any{}
		config["onboarding"] = onboarding
	}

	seen, ok := onboarding["seen"].(map[string]any)
	if !ok {
		seen = map[string]any{}
		onboarding["seen"] = seen
	}

	seen[onboardingFlag(flags)] = true
	return config
}

func onboardingSeenMap(config map[string]any) (map[string]any, bool) {
	onboarding, ok := config["onboarding"].(map[string]any)
	if !ok {
		return nil, false
	}
	seen, ok := onboarding["seen"].(map[string]any)
	return seen, ok
}

func onboardingFlag(flags []string) string {
	if len(flags) == 0 || flags[0] == "" {
		return OpenClawResidueCleanupFlag
	}
	return flags[0]
}

