	}
}

func TestToolProgressHintCLIAndGateway(t *testing.T) {
	for _, surface := range []string{"cli", "gateway"} {
		t.Run(surface, func(t *testing.T) {
			got := ToolProgressHint(surface)
			assertHintContains(t, got, "/verbose", "all -> new -> off", "only shows once")
			assertHintOmits(t, got, "Hermes", "display.tool_progress", "config.toml")
		})
	}
}

func TestOnboardingHintsUnknownInputsDegrade(t *testing.T) {
	for _, tc := range []struct {
		name string
		got  string
		want []string
	}{
		{name: "unknown busy mode", got: BusyInputHint("cli", "surprise"), want: []string{"interrupted", "/busy queue"}},
		{name: "unknown surface busy", got: BusyInputHint("unknown", "queue"), want: []string{"queued", "/busy interrupt", "only shows once"}},
		{name: "unknown surface tool", got: ToolProgressHint("unknown"), want: []string{"/verbose", "all -> new -> off", "only shows once"}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if strings.TrimSpace(tc.got) == "" {
				t.Fatal("hint is empty")
			}
			assertHintContains(t, tc.got, tc.want...)
		})
	}
}

func assertHintContains(t *testing.T, got string, wants ...string) {
	t.Helper()
	lower := strings.ToLower(got)
	for _, want := range wants {
		if !strings.Contains(lower, strings.ToLower(want)) {
			t.Fatalf("hint missing %q:\n%s", want, got)
		}
	}
}

func assertHintOmits(t *testing.T, got string, forbiddens ...string) {
	t.Helper()
	for _, forbidden := range forbiddens {
		if strings.Contains(got, forbidden) {
			t.Fatalf("hint contains %q:\n%s", forbidden, got)
		}
	}
}

package onboarding

import "testing"

func TestOnboardingSeen_MalformedConfigUnseen(t *testing.T) {
	tests := []struct {
		name string
		cfg  map[string]any
	}{
		{
			name: "missing onboarding",
			cfg:  map[string]any{},
		},
		{
			name: "non-map onboarding",
			cfg: map[string]any{
				"onboarding": "corrupted",
			},
		},
		{
			name: "non-map seen",
			cfg: map[string]any{
				"onboarding": map[string]any{
					"seen": "corrupted",
				},
			},
		},
		{
			name: "false openclaw residue flag",
			cfg: map[string]any{
				"onboarding": map[string]any{
					"seen": map[string]any{
						OpenClawResidueCleanupFlag: false,
					},
				},
			},
		},
		{
			name: "unrelated seen flag",
			cfg: map[string]any{
				"onboarding": map[string]any{
					"seen": map[string]any{
						"busy_input_prompt": true,
					},
				},
			},
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if OnboardingSeen(tt.cfg) {
				t.Fatalf("OnboardingSeen(%#v) = true, want false", tt.cfg)
			}
		})
	}
}

func TestOnboardingSeen_OpenClawResidueTrue(t *testing.T) {
	cfg := map[string]any{
		"onboarding": map[string]any{
			"seen": map[string]any{
				OpenClawResidueCleanupFlag: true,
			},
		},
	}

	if !OnboardingSeen(cfg) {
		t.Fatalf("OnboardingSeen(%#v) = false, want true", cfg)
	}
}

func TestMarkOnboardingSeen_InMemoryPreservesOtherFlags(t *testing.T) {
	cfg := map[string]any{
		"onboarding": map[string]any{
			"seen": map[string]any{
				"busy_input_prompt": true,
			},
		},
	}

	got := MarkOnboardingSeen(cfg)
	onboarding, ok := got["onboarding"].(map[string]any)
	if !ok {
		t.Fatalf("MarkOnboardingSeen(%#v) onboarding = %T, want map[string]any", cfg, got["onboarding"])
	}
	seen, ok := onboarding["seen"].(map[string]any)
	if !ok {
		t.Fatalf("MarkOnboardingSeen(%#v) onboarding.seen = %T, want map[string]any", cfg, onboarding["seen"])
	}

	if seen[OpenClawResidueCleanupFlag] != true {
		t.Fatalf("seen[%q] = %#v, want true", OpenClawResidueCleanupFlag, seen[OpenClawResidueCleanupFlag])
	}
	if seen["busy_input_prompt"] != true {
		t.Fatalf("seen[busy_input_prompt] = %#v, want preserved true", seen["busy_input_prompt"])
	}
}

